// Strict allowlist for the energygrid.alert.v1 payload. Anything outside the
// closed contract fails this execution (the webhook then answers non-2xx and
// the runtime logs alert_failed); nothing unvalidated reaches Telegram.
const items = $input.all();
if (items.length !== 1) throw new Error('EG_ALERT_ITEM_COUNT');
const body = items[0].json && items[0].json.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('EG_ALERT_BODY');

const KEYS = ['schema', 'event', 'timestamp', 'run_id', 'stage', 'status', 'support_ref', 'exit_code', 'counts', 'attention_required'];
const COUNT_KEYS = ['inventory', 'downloaded', 'present', 'failure'];
const STAGES = ['config', 'lock', 'list', 'fetch', 'publish', 'run'];
const STATUSES = ['RETRYABLE_NETWORK_FAILURE', 'LOGIN_FAILED', 'PORTAL_LAYOUT_CHANGED', 'DOWNLOAD_FAILED', 'INVALID_PDF', 'ARCHIVE_CONFLICT', 'STATE_INCONSISTENT', 'ACTION_REQUIRED', 'RUN_IN_PROGRESS', 'UNKNOWN'];

const keys = Object.keys(body);
if (keys.length !== KEYS.length || !KEYS.every((key) => keys.includes(key))) throw new Error('EG_ALERT_KEYS');
if (body.schema !== 'energygrid.alert.v1') throw new Error('EG_ALERT_SCHEMA');
if (body.event !== 'energygrid_run_failed') throw new Error('EG_ALERT_EVENT');
if (typeof body.timestamp !== 'string' || !/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ$/.test(body.timestamp)) throw new Error('EG_ALERT_TIMESTAMP');
if (typeof body.run_id !== 'string' || !/^([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|UNKNOWN)$/.test(body.run_id)) throw new Error('EG_ALERT_RUN_ID');
if (!STAGES.includes(body.stage)) throw new Error('EG_ALERT_STAGE');
if (!STATUSES.includes(body.status)) throw new Error('EG_ALERT_STATUS');
if (typeof body.support_ref !== 'string' || !/^[A-Z][A-Z0-9_]{0,63}$/.test(body.support_ref)) throw new Error('EG_ALERT_SUPPORT_REF');
if (!Number.isInteger(body.exit_code) || body.exit_code < -1 || body.exit_code > 255) throw new Error('EG_ALERT_EXIT_CODE');
if (typeof body.attention_required !== 'boolean') throw new Error('EG_ALERT_ATTENTION');
const counts = body.counts;
if (!counts || typeof counts !== 'object' || Array.isArray(counts)) throw new Error('EG_ALERT_COUNTS');
const countKeys = Object.keys(counts);
if (countKeys.length !== COUNT_KEYS.length || !COUNT_KEYS.every((key) => countKeys.includes(key))) throw new Error('EG_ALERT_COUNTS');
for (const key of COUNT_KEYS) {
  if (!Number.isInteger(counts[key]) || counts[key] < 0 || counts[key] > 1000000) throw new Error('EG_ALERT_COUNTS');
}

const lines = [
  body.attention_required ? 'EnergyGrid bill run FAILED - attention required' : 'EnergyGrid bill run skipped',
  '',
  'Stage: ' + body.stage,
  'Status: ' + body.status,
  'Reference: ' + body.support_ref,
  'Exit code: ' + body.exit_code,
  'Counts: inventory ' + counts.inventory + ', downloaded ' + counts.downloaded + ', present ' + counts.present + ', failed ' + counts.failure,
  'Run: ' + body.run_id,
  'Time (UTC): ' + body.timestamp,
];
return [{ json: { alert_text: lines.join('\n') } }];
